        "Hebrew",
        "<strong>Shof’tim (<em>שֹׁפְטִים</em>) — “judges, deliverers.”</strong> The Hebrew name is misleading in modern English: the <em>shofet</em> is not a courtroom judge but a charismatic military deliverer raised up by God in moments of crisis. The book’s structure is cyclical — apostasy, oppression, cry, deliverer, peace, apostasy — repeated through six major and six minor judges. Like Joshua, the book opens with the formula <em>after the death of</em>, deliberately chaining itself to the previous narrative.",
