    (
        6,
        11,
        "",
        "Gideon was beating out wheat in the wine press",
        "comm",
        "Note",
        "Note",
        "<strong>Gideon’s call.</strong> The setting is itself a quiet humiliation: threshing wheat is normally done on an exposed hilltop where the wind separates grain from chaff; doing it in a wine press (a sunken stone basin) means hiding from Midianite raiders. The angel’s greeting — “mighty man of valor” — to a man crouching in a hole is one of the great ironic addresses in scripture. The Gideon cycle (chs 6–8) is the longest in the book and turns repeatedly on the question: is Gideon a deliverer, or a flawed king-in-waiting? Chapter 8 ends with him refusing kingship in word (8:23) but acting as a king in deed (his ephod, his harem, his many sons).",
        'User original',
    ),
