        "m",
        "",
        "comm",
        "Note",
        "Note",
        """<strong>The generational lapse.</strong> Within a generation of Joshua’s death, the people "did not know Yahweh." The verse frames the entire downward spiral of Judges. Knowledge here is not informational but covenantal — "to know" Yahweh in the Deuteronomic sense is to live in relationship.""",
        'User original',
